import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../style/home.css';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  // Fetching data from the backend
  useEffect(() => {
    // Example: Fetch posts
    axios.get('http://localhost:5000/api/posts')
      .then(res => setPosts(res.data))
      .catch(err => console.log(err));

    axios.get('http://localhost:5000/api/notifications')
      .then(res => setNotifications(res.data))
      .catch(err => console.log(err));

    axios.get('http://localhost:5000/api/suggestions')
      .then(res => setSuggestions(res.data))
      .catch(err => console.log(err));
  }, []);

  // Handle Like Action
  const handleLike = (id) => {
    setPosts(posts.map(post => post.id === id ? { ...post, likes: post.likes + 1 } : post));
  };

  // Handle Comment Action
  const handleComment = (id) => {
    alert(`Comment on post ${id} functionality will be added soon!`);
  };

  return (
    <div className="home-container">
      {/* Left: Suggestions */}
      <div className="left-sidebar">
        <h3>Suggestions</h3>
        {suggestions.map(s => (
          <div key={s.id} className="suggestion-card">
            <p>{s.name}</p>
            <small>{s.branch}</small>
            <button>Connect</button>
          </div>
        ))}
      </div>

      {/* Middle: Posts */}
      <div className="main-feed">
        <h2>Home Feed</h2>
        {posts.map(post => (
          <div key={post.id} className="post-card">
            <h4>{post.user}</h4>
            <p>{post.content}</p>
            <div className="post-actions">
              <span onClick={() => handleLike(post.id)}>❤️ {post.likes}</span>
              <span onClick={() => handleComment(post.id)}>💬 {post.comments}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Right: Notifications */}
      <div className="right-sidebar">
        <h3>Notifications</h3>
        {notifications.map(n => (
          <div key={n.id} className="notification-card">
            <p>{n.text}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Home;
